//===- FuzzedDataProvider.h - Utility header for fuzz targets -------------===//
//
// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
// See https://llvm.org/LICENSE.txt for license information.
// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
//
// This is a locally-provided copy of the standard compiler-rt
// FuzzedDataProvider.h used to build the libhevc fuzzers outside OSS-Fuzz.
// It implements the subset of the API used by the libhevc fuzz targets.
//===----------------------------------------------------------------------===//

#ifndef LLVM_FUZZER_FUZZED_DATA_PROVIDER_H_
#define LLVM_FUZZER_FUZZED_DATA_PROVIDER_H_

#include <algorithm>
#include <climits>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <initializer_list>
#include <limits>
#include <string>
#include <type_traits>
#include <utility>
#include <vector>

class FuzzedDataProvider {
 public:
  // |data| is an array of length |size| that the FuzzedDataProvider wraps to
  // provide more granular access. |data| must outlive the FuzzedDataProvider.
  FuzzedDataProvider(const uint8_t *data, size_t size)
      : data_ptr_(data), remaining_bytes_(size) {}

  ~FuzzedDataProvider() = default;

  FuzzedDataProvider(const FuzzedDataProvider &) = delete;
  FuzzedDataProvider &operator=(const FuzzedDataProvider &) = delete;

  // Returns a std::vector containing |num_bytes| of input data. If fewer than
  // |num_bytes| of data remain, returns a shorter vector containing all of the
  // data that's left. Can be useful with APIs that require a std::vector.
  std::vector<uint8_t> ConsumeBytes(size_t num_bytes) {
    num_bytes = std::min(num_bytes, remaining_bytes_);
    return ConsumeBytes<uint8_t>(num_bytes);
  }

  // Similar to |ConsumeBytes|, but also appends the terminal zero at the end.
  // This is useful when passing the consumed data as a C-style string.
  std::vector<uint8_t> ConsumeBytesWithTerminator(size_t num_bytes) {
    num_bytes = std::min(num_bytes, remaining_bytes_);
    std::vector<uint8_t> result = ConsumeBytes<uint8_t>(num_bytes);
    result.push_back(0);
    return result;
  }

  // Returns a std::string containing |num_bytes| of input data. If fewer than
  // |num_bytes| of data remain, returns a shorter string containing all of the
  // data that's left.
  std::string ConsumeBytesAsString(size_t num_bytes) {
    num_bytes = std::min(num_bytes, remaining_bytes_);
    std::string result;
    result.reserve(num_bytes);
    for (size_t i = 0; i < num_bytes; ++i)
      result.push_back(data_ptr_[i]);
    ConsumeBytes<uint8_t>(num_bytes);
    return result;
  }

  // Returns a number in the range [min, max] by consuming bytes from the
  // input data. The value might not be uniformly distributed in the given
  // range. If there's no more input data, returns |min|. |min| must be less
  // than or equal to |max|.
  template <typename T> T ConsumeIntegralInRange(T min, T max) {
    static_assert(std::is_integral<T>::value, "An integral type is required.");
    static_assert(sizeof(T) <= sizeof(uint64_t), "Unsupported integral type.");

    if (min > max)
      abort();

    T range = max - min;
    if (range == 0)
      return min;

    // Determine the number of bytes needed to represent `range`.
    unsigned int num_bytes = 0;
    for (T value = range; value > 0; value >>= 8)
      ++num_bytes;

    // Consume `num_bytes` bytes of data.
    T result = 0;
    for (unsigned int i = 0; i < num_bytes; ++i)
      result = (result << 8) | ConsumeIntegral<uint8_t>();

    // Use modulo to map the result into the range.
    return min + static_cast<T>(result % (range + 1));
  }

  // Returns a std::string of length from 0 to |max_length|. When it runs out of
  // input data, returns what remains of the input. Designed to be more stable
  // with respect to a fuzzer inserting characters than just picking a random
  // length and then consuming that many bytes.
  std::string ConsumeRandomLengthString(size_t max_length) {
    // Reads bytes from the buffer and locates the '0' that terminates the
    // string. If it is not found, returns the full string.
    size_t pos = 0;
    while (pos < max_length && data_ptr_[pos] != 0 && remaining_bytes_ > 0) {
      ++pos;
      --remaining_bytes_;
    }
    std::string result(reinterpret_cast<const char *>(data_ptr_), pos);
    data_ptr_ += pos;
    return result;
  }

  // Returns a std::string containing all remaining bytes of the input data.
  std::string ConsumeRemainingBytesAsString() {
    return ConsumeBytesAsString(remaining_bytes_);
  }

  // Returns a std::vector<uint8_t> containing all remaining bytes of the input
  // data.
  std::vector<uint8_t> ConsumeRemainingBytes() {
    return ConsumeBytes(remaining_bytes_);
  }

  // Returns a number in the range [type's min, type's max]. The value might
  // not be uniformly distributed in the given range. If there's no more input
  // data, returns |min|.
  template <typename T> T ConsumeIntegral() {
    return ConsumeIntegralInRange(std::numeric_limits<T>::min(),
                                  std::numeric_limits<T>::max());
  }

  // Reads one byte and returns a bool, or false when no data remains.
  bool ConsumeBool() { return 1 & ConsumeIntegral<uint8_t>(); }

  // Returns a copy of the value selected from the given fixed-size |array|.
  template <typename T, size_t size> T PickValueInArray(const T (&array)[size]) {
    static_assert(size > 0, "The array must be non empty.");
    return array[ConsumeIntegralInRange<size_t>(0, size - 1)];
  }

  template <typename T, size_t size>
  T PickValueInArray(const std::initializer_list<T> list) {
    static_assert(size > 0, "The array must be non empty.");
    return *(list.begin() + ConsumeIntegralInRange<size_t>(0, size - 1));
  }

  // Return an enum value. The enum must start at 0 and be contiguous. It must
  // also contain |kMaxValue| aliased to its last (max) value. Such is the case
  // with a typical `enum class FooType : int {... kMaxValue = ...}`.
  template <typename T> T ConsumeEnum() {
    static_assert(std::is_enum<T>::value, "`T` must be an enum type.");
    return static_cast<T>(ConsumeIntegralInRange<uint32_t>(
        0, static_cast<uint32_t>(T::kMaxValue)));
  }

  // Returns a floating point number in the range [min, max]. The value might
  // not be uniformly distributed in the given range. If there's no more input
  // data, returns |min|. Note that |min| must be less than or equal to |max|,
  // and |min| and |max| must be finite.
  template <typename T> T ConsumeFloatingPointInRange(T min, T max) {
    static_assert(std::is_floating_point<T>::value,
                  "A floating point type is required.");

    if (min > max)
      abort();

    T range = .0;
    T result = min;
    constexpr T zero(.0);
    if (max > zero && min < zero && max > min + std::numeric_limits<T>::max()) {
      // The diff |max - min| would overflow the given floating point type. Use
      // the half of the diff as the range and consume a bool to decide whether
      // the result is in the first of the second part of the diff.
      range = (max / 2.0) - (min / 2.0);
      if (ConsumeBool()) {
        result += range;
      }
    } else {
      range = max - min;
    }

    return result + range * ConsumeFloatingPoint<T>();
  }

  // Returns a floating point number in the range [type's min, type's max]. The
  // value might not be uniformly distributed in the given range. If there's no
  // more input data, returns |min|.
  template <typename T> T ConsumeFloatingPoint() {
    return ConsumeFloatingPointInRange(std::numeric_limits<T>::lowest(),
                                       std::numeric_limits<T>::max());
  }

  // Returns a floating point number in the range [0.0, 1.0]. The value might
  // not be uniformly distributed in the given range. If there's no more input
  // data, returns 0.
  template <typename T> T ConsumeProbability() {
    return ConsumeFloatingPointInRange(T(0.0), T(1.0));
  }

  // Returns a floating point number in the range [min, max], with the
  // precision of the given type. The value might not be uniformly distributed
  // in the given range. If there's no more input data, returns |min|.
  template <typename T> T ConsumeFloat() {
    return ConsumeFloatingPointInRange<T>(std::numeric_limits<T>::lowest(),
                                          std::numeric_limits<T>::max());
  }

  // Prints the sequence of bytes in the input data.
  void PrintTo(std::ostream &os) const {
    for (size_t i = 0; i < remaining_bytes_; ++i)
      os << std::hex << std::setw(2) << std::setfill('0')
         << static_cast<unsigned int>(data_ptr_[i]);
  }

  // Returns the number of unconsumed bytes in the input data.
  size_t remaining_bytes() const { return remaining_bytes_; }

 private:
  template <typename T> std::vector<T> ConsumeBytes(size_t size) {
    static_assert(sizeof(T) == 1, "ConsumeBytes only supports 1 byte types.");
    std::vector<T> result(size);
    if (size == 0) {
      return result;
    }
    std::memcpy(result.data(), data_ptr_, size);
    Advance(size);
    return result;
  }

  void Advance(size_t num_bytes) {
    if (num_bytes > remaining_bytes_)
      abort();
    data_ptr_ += num_bytes;
    remaining_bytes_ -= num_bytes;
  }

  const uint8_t *data_ptr_;
  size_t remaining_bytes_;
};

#endif // LLVM_FUZZER_FUZZED_DATA_PROVIDER_H_

